namespace cosmictiger::gravity::spherical {
void evaluateEwaldGreen(SimdVector<float, 8>& greenTrace, SimdVector<float, 8> x,
    SimdVector<float, 8> y, SimdVector<float, 8> z, SimdVector<float, 8>* output) {
    using namespace math;
    using Working = typename detail::EwaldWorkingType<SimdVector<float, 8>>::Type;
    Working temporary[49];
    Working trace;
    evaluateEwaldWorking(trace, detail::ewaldConvert<Working>(x), detail::ewaldConvert<Working>(y),
        detail::ewaldConvert<Working>(z), temporary);
    for (int i = 0; i < 49; ++i) {
        output[i] = detail::ewaldConvert<SimdVector<float, 8>>(temporary[i]);
    }
    greenTrace = detail::ewaldConvert<SimdVector<float, 8>>(trace);
}
}    // namespace cosmictiger::gravity::spherical
